/**
 * The big offline quote library: every row becomes one English and one Bangla quote.
 *
 * Islamic rows are meanings (not word-for-word translations) of Quran verses and well-known
 * authentic hadith, each with its reference. General rows are Dinrekha's own lines — no
 * misattributed "famous quotes".
 */
object QuoteLibrary {

    private sealed interface Row { val en: String; val bn: String }
    private class Q(val sura: Int, val ayah: String, override val en: String, override val bn: String) : Row
    private class H(val book: Book, val num: String, override val en: String, override val bn: String) : Row
    private class G(override val en: String, override val bn: String) : Row

    private enum class Book(val en: String, val bn: String) {
        BUKHARI("Sahih al-Bukhari", "সহীহ বুখারী"),
        MUSLIM("Sahih Muslim", "সহীহ মুসলিম"),
        BUKHARI_MUSLIM("Bukhari & Muslim", "বুখারী ও মুসলিম"),
        TIRMIDHI("Jami at-Tirmidhi", "জামে তিরমিযী"),
        ABU_DAWUD("Sunan Abi Dawud", "সুনান আবু দাউদ"),
        HAKIM("Al-Mustadrak al-Hakim", "মুস্তাদরাক হাকিম"),
        BAYHAQI("Al-Bayhaqi, Shu'ab al-Iman", "বায়হাকী, শুআবুল ঈমান"),
        TABARANI("Al-Tabarani, al-Mu'jam al-Awsat", "তাবারানী, আল-মুজামুল আওসাত"),
    }

