    private fun bnDigits(s: String) = s.map { if (it in '0'..'9') '০' + (it - '0') else it }.joinToString("")

    private val ROWS: List<Row> = listOf(
        // ============================================================ Quran
        Q(94, "5-6", "Indeed, with hardship comes ease. Indeed, with hardship comes ease.", "নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে। নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে।"),
        Q(2, "286", "Allah does not burden a soul beyond what it can bear.", "আল্লাহ কাউকে তার সাধ্যের বাইরে বোঝা দেন না।"),
        Q(13, "11", "Allah does not change the condition of a people until they change what is in themselves.", "আল্লাহ কোনো জাতির অবস্থা বদলান না, যতক্ষণ না তারা নিজেরা নিজেদের বদলায়।"),
        Q(2, "153", "Seek help through patience and prayer. Indeed, Allah is with the patient.", "ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও। নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন।"),
        Q(65, "3", "Whoever relies upon Allah, He is sufficient for him.", "যে আল্লাহর উপর ভরসা করে, তার জন্য তিনিই যথেষ্ট।"),
        Q(65, "2", "Whoever is mindful of Allah, He will make a way out for him.", "যে আল্লাহকে ভয় করে, আল্লাহ তার জন্য বের হওয়ার পথ করে দেন।"),
        Q(39, "53", "Do not despair of the mercy of Allah.", "আল্লাহর রহমত থেকে নিরাশ হয়ো না।"),
        Q(3, "139", "Do not lose heart and do not grieve; you will be uppermost if you are believers.", "তোমরা হীনবল হয়ো না, দুঃখ করো না; তোমরাই বিজয়ী হবে যদি তোমরা মুমিন হও।"),
        Q(53, "39", "A person will have nothing except what he strives for.", "মানুষ তা-ই পায়, যার জন্য সে চেষ্টা করে।"),
        Q(20, "114", "My Lord, increase me in knowledge.", "হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন।"),
        Q(2, "152", "So remember Me; I will remember you.", "তোমরা আমাকে স্মরণ করো, আমিও তোমাদের স্মরণ করব।"),
        Q(13, "28", "Surely, in the remembrance of Allah do hearts find rest.", "জেনে রাখো, আল্লাহর স্মরণেই অন্তর প্রশান্তি পায়।"),
        Q(29, "69", "Those who strive for Us, We will surely guide them to Our ways.", "যারা আমার পথে চেষ্টা করে, আমি অবশ্যই তাদের আমার পথ দেখাব।"),
        Q(2, "216", "Perhaps you dislike something and it is good for you.", "হয়তো তোমরা কোনো কিছু অপছন্দ করো, অথচ তা তোমাদের জন্য কল্যাণকর।"),
        Q(3, "159", "When you have made a decision, then rely upon Allah.", "যখন সিদ্ধান্ত নেবে, তখন আল্লাহর উপর ভরসা করো।"),
        Q(8, "46", "Be patient. Indeed, Allah is with the patient.", "ধৈর্য ধরো। নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন।"),
        Q(40, "60", "Call upon Me; I will respond to you.", "তোমরা আমাকে ডাকো, আমি তোমাদের ডাকে সাড়া দেব।"),
        Q(2, "186", "I am near. I respond to the call of the one who calls upon Me.", "আমি তো কাছেই আছি। কেউ আমাকে ডাকলে আমি তার ডাকে সাড়া দিই।"),
        Q(14, "7", "If you are grateful, I will surely give you more.", "যদি তোমরা কৃতজ্ঞ হও, আমি অবশ্যই তোমাদের আরও দেব।"),
        Q(49, "13", "The most noble of you in the sight of Allah is the most righteous of you.", "আল্লাহর কাছে তোমাদের মধ্যে সবচেয়ে সম্মানিত সে, যে সবচেয়ে বেশি তাকওয়াবান।"),
        Q(103, "1-3", "By time, people are in loss, except those who believe, do good, and urge one another to truth and patience.", "সময়ের শপথ, মানুষ ক্ষতির মধ্যে আছে; তারা ছাড়া যারা ঈমান আনে, ভালো কাজ করে, সত্য ও ধৈর্যের উপদেশ দেয়।"),
        Q(20, "25-26", "My Lord, open my heart for me and make my task easy for me.", "হে আমার রব, আমার বুক প্রশস্ত করে দিন এবং আমার কাজ সহজ করে দিন।"),
        Q(21, "87", "There is no god but You, glory be to You; I have been among the wrongdoers.", "আপনি ছাড়া কোনো ইলাহ নেই, আপনি পবিত্র; নিশ্চয়ই আমি ছিলাম জালিমদের অন্তর্ভুক্ত।"),
        Q(3, "173", "Allah is enough for us, and He is the best disposer of affairs.", "আমাদের জন্য আল্লাহই যথেষ্ট, আর তিনিই উত্তম কর্মবিধায়ক।"),
        Q(12, "87", "Do not lose hope in the relief of Allah.", "আল্লাহর রহমত থেকে নিরাশ হয়ো না।"),
        Q(25, "63", "The servants of the Most Merciful walk on the earth humbly.", "রহমানের বান্দা তারা, যারা পৃথিবীতে নম্রভাবে চলাফেরা করে।"),
        Q(31, "17", "Be patient with whatever befalls you; that is a matter of real resolve.", "তোমার উপর যা আসে তাতে ধৈর্য ধরো; এটা দৃঢ় সংকল্পের কাজ।"),
        Q(41, "34", "Repel evil with what is better.", "মন্দকে প্রতিহত করো যা উত্তম তা দিয়ে।"),
        Q(17, "36", "Do not follow what you have no knowledge of.", "যে বিষয়ে তোমার জ্ঞান নেই, তার পেছনে পড়ো না।"),
        Q(4, "28", "Allah wants to lighten your burden, for people were created weak.", "আল্লাহ তোমাদের বোঝা হালকা করতে চান; মানুষকে দুর্বল করে সৃষ্টি করা হয়েছে।"),
        Q(2, "185", "Allah wants ease for you, not hardship.", "আল্লাহ তোমাদের জন্য সহজ চান, কঠিন চান না।"),
        Q(57, "4", "He is with you wherever you are.", "তোমরা যেখানেই থাকো, তিনি তোমাদের সাথে আছেন।"),
        Q(50, "16", "We are closer to him than his jugular vein.", "আমি তার গলার শিরার চেয়েও তার বেশি কাছে।"),
        Q(93, "3", "Your Lord has not abandoned you, nor is He displeased.", "তোমার রব তোমাকে ত্যাগ করেননি, অসন্তুষ্টও হননি।"),
        Q(93, "4", "What is coming is better for you than what has passed.", "তোমার জন্য পরবর্তী সময় পূর্ববর্তী সময়ের চেয়ে উত্তম।"),
        Q(93, "5", "Your Lord will give you, and you will be pleased.", "তোমার রব তোমাকে দেবেন, আর তুমি সন্তুষ্ট হবে।"),
        Q(94, "7-8", "When you have finished one task, work on the next, and turn to your Lord with longing.", "যখন একটি কাজ শেষ করো, পরের কাজে লেগে যাও, আর তোমার রবের দিকে মনোযোগী হও।"),
        Q(39, "10", "The patient will be given their reward without measure.", "ধৈর্যশীলদের পুরস্কার দেওয়া হবে হিসাব ছাড়াই।"),
        Q(16, "97", "Whoever does good, man or woman, with faith, We will give them a good life.", "নারী হোক বা পুরুষ, ঈমান নিয়ে যে ভালো কাজ করে, আমি তাকে উত্তম জীবন দান করব।"),
        Q(18, "46", "Wealth and children adorn this life, but lasting good deeds are better with your Lord.", "সম্পদ ও সন্তান দুনিয়ার সৌন্দর্য, কিন্তু স্থায়ী ভালো কাজ তোমার রবের কাছে উত্তম।"),
        Q(3, "200", "Be patient, persevere, stay steadfast and be mindful of Allah, so that you may succeed.", "ধৈর্য ধরো, অবিচল থাকো, দৃঢ় থাকো এবং আল্লাহকে ভয় করো, যাতে সফল হও।"),
        Q(7, "56", "The mercy of Allah is near to those who do good.", "আল্লাহর রহমত সৎকর্মশীলদের নিকটবর্তী।"),
        Q(11, "115", "Be patient; Allah does not let the reward of those who do good go to waste.", "ধৈর্য ধরো; আল্লাহ সৎকর্মশীলদের প্রতিদান নষ্ট করেন না।"),
        Q(33, "41", "Remember Allah often.", "আল্লাহকে বেশি বেশি স্মরণ করো।"),
        Q(62, "10", "When the prayer is over, go out in the land and seek the bounty of Allah.", "নামাজ শেষ হলে পৃথিবীতে ছড়িয়ে পড়ো এবং আল্লাহর অনুগ্রহ সন্ধান করো।"),
        Q(67, "2", "He created death and life to test which of you is best in deeds.", "তিনি মৃত্যু ও জীবন সৃষ্টি করেছেন, পরীক্ষা করার জন্য কে কাজে উত্তম।"),
        Q(4, "103", "Prayer is prescribed for the believers at fixed times.", "নির্ধারিত সময়ে নামাজ পড়া মুমিনদের উপর ফরজ।"),
        Q(28, "77", "Do not forget your share of this world, and do good as Allah has done good to you.", "দুনিয়া থেকে তোমার অংশ ভুলে যেও না, আর ভালো করো যেমন আল্লাহ তোমার প্রতি ভালো করেছেন।"),
        Q(5, "2", "Help one another in goodness and piety.", "ভালো কাজ ও তাকওয়ায় একে অপরকে সাহায্য করো।"),
        Q(49, "12", "Avoid much suspicion, do not spy, and do not backbite.", "বেশি অনুমান থেকে বাঁচো, গোয়েন্দাগিরি করো না, গীবত করো না।"),
        Q(17, "53", "Tell My servants to say what is best.", "আমার বান্দাদের বলো, তারা যেন উত্তম কথা বলে।"),
        Q(2, "83", "Speak to people kindly.", "মানুষের সাথে সুন্দরভাবে কথা বলো।"),
        Q(7, "31", "Eat and drink, but do not waste.", "খাও ও পান করো, কিন্তু অপচয় করো না।"),
        Q(25, "67", "When they spend, they are neither wasteful nor stingy, but balanced between the two.", "তারা যখন খরচ করে, অপচয়ও করে না, কৃপণতাও করে না; বরং মাঝামাঝি থাকে।"),
        Q(17, "27", "Wasteful people are the brothers of the devils.", "অপচয়কারীরা শয়তানের ভাই।"),
        Q(78, "9-10", "We made your sleep for rest, and the night a covering.", "আমি তোমাদের ঘুমকে বিশ্রাম বানিয়েছি, আর রাতকে করেছি আবরণ।"),
        Q(25, "47", "He made the night a covering for you, sleep for rest, and the day for rising.", "তিনি রাতকে তোমাদের জন্য আবরণ, ঘুমকে বিশ্রাম আর দিনকে কর্মের জন্য বানিয়েছেন।"),
        Q(30, "23", "Among His signs is your sleep by night and day, and your seeking of His bounty.", "তাঁর নিদর্শনের মধ্যে আছে রাতে ও দিনে তোমাদের ঘুম এবং তাঁর অনুগ্রহ সন্ধান।"),
        Q(6, "162", "My prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds.", "আমার নামাজ, আমার কুরবানি, আমার জীবন ও মরণ সবই বিশ্বজগতের রব আল্লাহর জন্য।"),
        Q(1, "5", "You alone we worship, and You alone we ask for help.", "আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই সাহায্য চাই।"),
        Q(96, "1", "Read in the name of your Lord who created.", "পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন।"),
        Q(58, "11", "Allah raises in rank those who believe and those given knowledge.", "আল্লাহ মুমিনদের এবং যাদের জ্ঞান দেওয়া হয়েছে তাদের মর্যাদা বাড়িয়ে দেন।"),
        Q(39, "9", "Are those who know equal to those who do not know?", "যারা জানে আর যারা জানে না, তারা কি সমান?"),
        Q(2, "269", "Whoever is given wisdom has been given much good.", "যাকে প্রজ্ঞা দেওয়া হয়েছে, তাকে অনেক কল্যাণ দেওয়া হয়েছে।"),
        Q(3, "134", "Those who control their anger and forgive people; Allah loves those who do good.", "যারা রাগ সংবরণ করে এবং মানুষকে ক্ষমা করে; আল্লাহ সৎকর্মশীলদের ভালোবাসেন।"),
        Q(42, "43", "Whoever is patient and forgives, that is a sign of true resolve.", "যে ধৈর্য ধরে ও ক্ষমা করে, নিশ্চয়ই তা দৃঢ় সংকল্পের কাজ।"),
        Q(64, "16", "Be mindful of Allah as much as you are able.", "যতটুকু পারো আল্লাহকে ভয় করো।"),
        Q(2, "155", "We will test you with some fear, hunger and loss; give good news to the patient.", "আমি তোমাদের কিছু ভয়, ক্ষুধা ও ক্ষতি দিয়ে পরীক্ষা করব; ধৈর্যশীলদের সুসংবাদ দাও।"),
        Q(2, "156", "Truly we belong to Allah, and to Him we will return.", "নিশ্চয়ই আমরা আল্লাহর জন্য এবং তাঁর কাছেই ফিরে যাব।"),
        Q(3, "8", "Our Lord, do not let our hearts stray after You have guided us.", "হে আমাদের রব, হেদায়াত দেওয়ার পর আমাদের অন্তর বাঁকা করে দেবেন না।"),
        Q(2, "201", "Our Lord, give us good in this world and good in the Hereafter, and protect us from the Fire.", "হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতে কল্যাণ দিন এবং আগুনের শাস্তি থেকে বাঁচান।"),
        Q(25, "74", "Our Lord, grant us spouses and children who are the coolness of our eyes.", "হে আমাদের রব, আমাদের এমন স্ত্রী ও সন্তান দিন, যারা হবে চোখের শীতলতা।"),
        Q(14, "40", "My Lord, make me one who keeps up the prayer, and my children too.", "হে আমার রব, আমাকে নামাজ কায়েমকারী বানান এবং আমার সন্তানদেরও।"),
        Q(17, "24", "My Lord, have mercy on my parents as they raised me when I was small.", "হে আমার রব, তাদের প্রতি দয়া করুন, যেমন তারা ছোটবেলায় আমাকে লালন-পালন করেছেন।"),
        Q(18, "10", "Our Lord, grant us mercy from You and guide us rightly in our affair.", "হে আমাদের রব, আপনার কাছ থেকে আমাদের রহমত দিন এবং আমাদের কাজ সঠিক করে দিন।"),
        Q(28, "24", "My Lord, I am truly in need of whatever good You send me.", "হে আমার রব, আপনি আমার প্রতি যে কল্যাণই নাজিল করবেন, আমি তার মুখাপেক্ষী।"),
        Q(47, "7", "If you stand for Allah, He will help you and make your feet firm.", "যদি তোমরা আল্লাহকে সাহায্য করো, তিনি তোমাদের সাহায্য করবেন এবং পা দৃঢ় রাখবেন।"),
        Q(2, "110", "Whatever good you send ahead for yourselves, you will find it with Allah.", "নিজেদের জন্য যে ভালো কাজ আগে পাঠাবে, তা আল্লাহর কাছে পাবে।"),
        Q(99, "7", "Whoever does an atom's weight of good will see it.", "যে অণু পরিমাণ ভালো কাজ করবে, সে তা দেখতে পাবে।"),
        Q(55, "60", "Is the reward for good anything but good?", "উত্তম কাজের প্রতিদান উত্তম ছাড়া আর কী হতে পারে?"),
        Q(87, "14-15", "Successful is the one who purifies himself, remembers his Lord and prays.", "সফল সে, যে নিজেকে পরিশুদ্ধ করে, রবের নাম স্মরণ করে ও নামাজ পড়ে।"),
        Q(23, "1-3", "Successful are the believers who are humble in prayer and turn away from idle talk.", "সফল সেই মুমিনরা, যারা নামাজে বিনয়ী এবং অনর্থক কথা থেকে দূরে থাকে।"),
        Q(29, "45", "Prayer keeps one away from shameful and wrong deeds.", "নিশ্চয়ই নামাজ অশ্লীল ও মন্দ কাজ থেকে বিরত রাখে।"),
        Q(20, "132", "Enjoin prayer on your family, and be steadfast in it yourself.", "তোমার পরিবারকে নামাজের আদেশ দাও এবং নিজেও তাতে অবিচল থাকো।"),
        Q(11, "114", "Good deeds wipe away bad deeds.", "নিশ্চয়ই ভালো কাজ মন্দ কাজকে মুছে দেয়।"),
        Q(24, "22", "Let them forgive and overlook. Would you not love for Allah to forgive you?", "তারা যেন ক্ষমা করে ও উপেক্ষা করে। তোমরা কি চাও না আল্লাহ তোমাদের ক্ষমা করুন?"),
        Q(3, "92", "You will not attain righteousness until you spend from what you love.", "তোমরা প্রিয় জিনিস থেকে খরচ না করা পর্যন্ত কখনো পুণ্য অর্জন করতে পারবে না।"),
        Q(2, "195", "Do good; Allah loves those who do good.", "ভালো কাজ করো; আল্লাহ সৎকর্মশীলদের ভালোবাসেন।"),
        Q(31, "19", "Be moderate in your pace and lower your voice.", "চলাফেরায় মধ্যপন্থা অবলম্বন করো এবং কণ্ঠস্বর নিচু রাখো।"),
        Q(59, "18", "Let every soul look to what it has sent ahead for tomorrow.", "প্রত্যেকে যেন ভেবে দেখে, আগামীকালের জন্য সে কী পাঠিয়েছে।"),
        Q(16, "18", "If you tried to count the blessings of Allah, you could never count them.", "তোমরা আল্লাহর নিয়ামত গুনতে চাইলে কখনো গুনে শেষ করতে পারবে না।"),
        Q(55, "13", "So which of the favours of your Lord will you deny?", "অতএব তোমরা তোমাদের রবের কোন কোন নিয়ামত অস্বীকার করবে?"),
        Q(61, "2-3", "Why do you say what you do not do?", "তোমরা এমন কথা কেন বলো, যা তোমরা করো না?"),
        Q(9, "105", "Work, for Allah will see your work.", "তোমরা কাজ করো; আল্লাহ তোমাদের কাজ দেখবেন।"),
        Q(9, "51", "Nothing will befall us except what Allah has written for us.", "আল্লাহ আমাদের জন্য যা লিখে রেখেছেন, তা ছাড়া কিছুই আমাদের হবে না।"),
        Q(16, "128", "Allah is with those who are mindful of Him and those who do good.", "আল্লাহ তাদের সাথে আছেন যারা তাঁকে ভয় করে এবং যারা সৎকর্মশীল।"),
        Q(35, "28", "Of His servants, only those with knowledge truly stand in awe of Allah.", "আল্লাহর বান্দাদের মধ্যে জ্ঞানীরাই তাঁকে সবচেয়ে বেশি ভয় করে।"),
        Q(51, "56", "I created jinn and humans only to worship Me.", "আমি জিন ও মানুষকে শুধু আমার ইবাদতের জন্যই সৃষ্টি করেছি।"),
        Q(2, "45", "Seek help through patience and prayer.", "ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও।"),

        // ============================================================ Hadith
        H(Book.BUKHARI, "1", "Actions are judged by intentions.", "সকল কাজ নিয়তের উপর নির্ভরশীল।"),
        H(Book.BUKHARI_MUSLIM, "Bukhari 6464, Muslim 783", "The deeds most beloved to Allah are the most consistent, even if small.", "আল্লাহর কাছে সবচেয়ে প্রিয় আমল তা-ই, যা নিয়মিত করা হয়, যদিও তা অল্প হয়।"),
        H(Book.HAKIM, "7846", "Take advantage of five before five: youth before old age, health before sickness, wealth before poverty, free time before busyness, and life before death.", "পাঁচটি জিনিসের আগে পাঁচটিকে কাজে লাগাও: বার্ধক্যের আগে যৌবন, অসুস্থতার আগে সুস্থতা, দারিদ্র্যের আগে সচ্ছলতা, ব্যস্ততার আগে অবসর, আর মৃত্যুর আগে জীবন।"),
        H(Book.BUKHARI, "6412", "Two blessings many people waste: health and free time.", "দুটি নিয়ামতের ব্যাপারে অনেক মানুষ ক্ষতিগ্রস্ত: সুস্থতা ও অবসর সময়।"),
        H(Book.MUSLIM, "2664", "The strong believer is better and more beloved to Allah than the weak believer. Strive for what benefits you, seek Allah's help, and do not give up.", "শক্তিশালী মুমিন দুর্বল মুমিনের চেয়ে উত্তম ও আল্লাহর কাছে বেশি প্রিয়। যা তোমার উপকারে আসে তার চেষ্টা করো, আল্লাহর সাহায্য চাও, আর হাল ছেড়ো না।"),
        H(Book.MUSLIM, "2699", "Whoever takes a path in search of knowledge, Allah makes easy for him a path to Paradise.", "যে জ্ঞান অর্জনের পথে চলে, আল্লাহ তার জন্য জান্নাতের পথ সহজ করে দেন।"),
        H(Book.BUKHARI, "13", "None of you truly believes until he loves for his brother what he loves for himself.", "তোমাদের কেউ প্রকৃত মুমিন হবে না, যতক্ষণ না সে নিজের জন্য যা পছন্দ করে, ভাইয়ের জন্যও তা পছন্দ করে।"),
        H(Book.TIRMIDHI, "1956", "Your smile in the face of your brother is charity.", "তোমার ভাইয়ের দিকে হাসিমুখে তাকানোও সদকা।"),
        H(Book.BUKHARI, "6114", "The strong one is not the one who wrestles others down, but the one who controls himself when angry.", "কুস্তিতে হারিয়ে দেওয়া ব্যক্তি শক্তিশালী নয়; শক্তিশালী সে, যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে।"),
        H(Book.MUSLIM, "2564", "Allah does not look at your appearance or your wealth, but at your hearts and your deeds.", "আল্লাহ তোমাদের চেহারা ও সম্পদের দিকে তাকান না, বরং তোমাদের অন্তর ও আমলের দিকে তাকান।"),
        H(Book.BUKHARI, "69", "Make things easy, not difficult. Give good news, and do not drive people away.", "সহজ করো, কঠিন করো না। সুসংবাদ দাও, মানুষকে দূরে ঠেলে দিও না।"),
        H(Book.TIRMIDHI, "2517", "Tie your camel, then put your trust in Allah.", "আগে উট বাঁধো, তারপর আল্লাহর উপর ভরসা করো।"),
        H(Book.BUKHARI, "6416", "Be in this world as if you were a stranger or a traveller.", "দুনিয়াতে এমনভাবে থাকো, যেন তুমি একজন অপরিচিত বা পথিক।"),
        H(Book.TIRMIDHI, "2317", "Part of a person's good Islam is leaving what does not concern him.", "অনর্থক বিষয় ত্যাগ করা একজন মানুষের সুন্দর ইসলামের অংশ।"),
        H(Book.BUKHARI, "1429", "The upper hand is better than the lower hand.", "উপরের হাত (দানকারী) নিচের হাতের (গ্রহীতার) চেয়ে উত্তম।"),
        H(Book.BAYHAQI, "", "Allah loves that when one of you does a task, he does it with excellence.", "আল্লাহ পছন্দ করেন, তোমাদের কেউ যখন কোনো কাজ করে, তা যেন নিখুঁতভাবে করে।"),
        H(Book.TIRMIDHI, "3895", "The best of you are those who are best to their families.", "তোমাদের মধ্যে সর্বোত্তম সে, যে তার পরিবারের কাছে সর্বোত্তম।"),
        H(Book.BUKHARI, "6018", "Whoever believes in Allah and the Last Day, let him speak good or stay silent.", "যে আল্লাহ ও শেষ দিনে বিশ্বাস করে, সে যেন ভালো কথা বলে অথবা চুপ থাকে।"),
        H(Book.TIRMIDHI, "2516", "Be mindful of Allah, and He will protect you.", "আল্লাহর বিধান রক্ষা করো, আল্লাহ তোমাকে রক্ষা করবেন।"),
        H(Book.MUSLIM, "2588", "Charity does not decrease wealth.", "সদকা করলে সম্পদ কমে না।"),
        H(Book.BUKHARI, "6927", "Allah is gentle and loves gentleness in all matters.", "আল্লাহ কোমল, তিনি সব কাজে কোমলতা পছন্দ করেন।"),
        H(Book.MUSLIM, "2999", "How wonderful the affair of the believer: if good comes he is grateful, if hardship comes he is patient, and both are good for him.", "মুমিনের ব্যাপারটা কত চমৎকার! সুখে সে কৃতজ্ঞ হয়, দুঃখে ধৈর্য ধরে, আর দুটোই তার জন্য কল্যাণ।"),
        H(Book.MUSLIM, "223", "Purity is half of faith.", "পবিত্রতা ঈমানের অর্ধেক।"),
        H(Book.BUKHARI, "6021", "Every good deed is charity.", "প্রত্যেক ভালো কাজই সদকা।"),
        H(Book.BUKHARI, "6116", "Do not become angry.", "রাগ করো না।"),
        H(Book.BUKHARI, "6133", "A believer is not stung from the same hole twice.", "মুমিন একই গর্ত থেকে দুবার দংশিত হয় না।"),
        H(Book.TIRMIDHI, "2518", "Leave what makes you doubt for what does not make you doubt.", "যা তোমাকে সন্দেহে ফেলে তা ছেড়ে দাও, যা সন্দেহে ফেলে না তা গ্রহণ করো।"),
        H(Book.TIRMIDHI, "1987", "Be mindful of Allah wherever you are, follow a bad deed with a good one to wipe it out, and treat people with good character.", "যেখানেই থাকো আল্লাহকে ভয় করো, মন্দ কাজের পর ভালো কাজ করো যা তা মুছে দেবে, আর মানুষের সাথে সুন্দর আচরণ করো।"),
        H(Book.BUKHARI, "6446", "Richness is not having many things; true richness is a content soul.", "সম্পদের আধিক্য প্রকৃত সচ্ছলতা নয়; প্রকৃত সচ্ছলতা হলো অন্তরের সচ্ছলতা।"),
        H(Book.BUKHARI, "527", "The deed most beloved to Allah is prayer at its proper time.", "আল্লাহর কাছে সবচেয়ে প্রিয় আমল হলো সময়মতো নামাজ পড়া।"),
        H(Book.ABU_DAWUD, "2606", "O Allah, bless my nation in their early mornings.", "হে আল্লাহ, আমার উম্মতের জন্য ভোরবেলায় বরকত দিন।"),
        H(Book.ABU_DAWUD, "4811", "Whoever does not thank people has not thanked Allah.", "যে মানুষের কৃতজ্ঞতা স্বীকার করে না, সে আল্লাহরও কৃতজ্ঞতা স্বীকার করে না।"),
        H(Book.BUKHARI, "6117", "Modesty brings nothing but good.", "লজ্জাশীলতা কেবল কল্যাণই বয়ে আনে।"),
        H(Book.BUKHARI, "6013", "Whoever does not show mercy will not be shown mercy.", "যে দয়া করে না, তার প্রতিও দয়া করা হয় না।"),
        H(Book.ABU_DAWUD, "4833", "A person follows the way of his close friend, so look at whom you befriend.", "মানুষ তার বন্ধুর পথে চলে; তাই দেখো তুমি কাকে বন্ধু বানাচ্ছ।"),
        H(Book.TIRMIDHI, "2417", "On the Day of Judgment, each person will be asked about his life, his knowledge, his wealth and his body, and how he used them.", "কিয়ামতের দিন প্রত্যেককে জিজ্ঞেস করা হবে তার জীবন, জ্ঞান, সম্পদ ও শরীর সম্পর্কে, কীভাবে সে তা ব্যবহার করেছে।"),
        H(Book.BUKHARI, "568", "The Prophet disliked sleeping before Isha and chatting after it.", "নবীজি (সা.) এশার আগে ঘুমানো এবং এশার পরে গল্পগুজব করা অপছন্দ করতেন।"),
        H(Book.TABARANI, "", "The best of people are those most beneficial to people.", "মানুষের মধ্যে সর্বোত্তম সে, যে মানুষের সবচেয়ে বেশি উপকার করে।"),
        H(Book.MUSLIM, "2963", "Look at those below you, not those above you; that keeps you from belittling Allah's blessings.", "তোমার চেয়ে নিচের দিকে তাকাও, উপরের দিকে নয়; এতে আল্লাহর নিয়ামতকে তুচ্ছ মনে হবে না।"),
        H(Book.MUSLIM, "1955", "Allah has prescribed excellence in everything.", "আল্লাহ প্রতিটি বিষয়ে উত্তমতা নির্ধারণ করেছেন।"),
        H(Book.BUKHARI, "39", "The religion is easy. Be moderate, aim for what is right, and take help from the morning, the evening and part of the night.", "দ্বীন সহজ। মধ্যপন্থা অবলম্বন করো, সঠিকের কাছাকাছি থাকো, আর সকাল, সন্ধ্যা ও রাতের কিছু অংশ কাজে লাগাও।"),
        H(Book.MUSLIM, "1631", "When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.", "মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: চলমান সদকা, উপকারী জ্ঞান, অথবা নেক সন্তান যে তার জন্য দোয়া করে।"),
        H(Book.MUSLIM, "1893", "Whoever guides someone to good gets a reward like the one who does it.", "যে কাউকে ভালো কাজের পথ দেখায়, সে ঐ কাজ সম্পাদনকারীর মতো সওয়াব পায়।"),
        H(Book.BUKHARI, "6369", "O Allah, I seek refuge in You from worry and grief, from weakness and laziness.", "হে আল্লাহ, আমি আপনার কাছে আশ্রয় চাই দুশ্চিন্তা ও দুঃখ থেকে, অক্ষমতা ও অলসতা থেকে।"),
        H(Book.MUSLIM, "2699", "Whoever relieves a believer of a hardship of this world, Allah will relieve him of a hardship on the Day of Judgment.", "যে কোনো মুমিনের দুনিয়ার একটি কষ্ট দূর করে, আল্লাহ কিয়ামতের দিন তার একটি কষ্ট দূর করবেন।"),
        H(Book.TIRMIDHI, "2346", "Whoever wakes up safe, healthy, and with food for the day, it is as if the whole world were given to him.", "যে নিরাপদে, সুস্থ শরীরে এবং দিনের খাবার নিয়ে সকালে ঘুম থেকে ওঠে, যেন তাকে পুরো দুনিয়া দিয়ে দেওয়া হয়েছে।"),
        H(Book.MUSLIM, "118", "Hurry to do good deeds before trials come like pieces of a dark night.", "অন্ধকার রাতের মতো ফিতনা আসার আগেই দ্রুত ভালো কাজ করো।"),
        H(Book.BUKHARI, "5027", "The best of you are those who learn the Quran and teach it.", "তোমাদের মধ্যে সর্বোত্তম সে, যে কুরআন শেখে এবং শেখায়।"),
        H(Book.MUSLIM, "55", "The religion is sincerity.", "দ্বীন হলো কল্যাণকামিতা।"),
        H(Book.TIRMIDHI, "2507", "The believer who mixes with people and bears their harm patiently is better than one who keeps away and does not.", "যে মুমিন মানুষের সাথে মেশে এবং তাদের কষ্টে ধৈর্য ধরে, সে তার চেয়ে উত্তম যে মেশে না ও ধৈর্য ধরে না।"),

        // ============================================================ Discipline, study, focus (Dinrekha's own)
        G("Start small. Five focused minutes beat an hour of planning.", "ছোট করে শুরু করো। এক ঘণ্টা পরিকল্পনার চেয়ে পাঁচ মিনিট মনোযোগী কাজ ভালো।"),
        G("You don't need motivation to begin. Begin, and motivation follows.", "শুরু করতে মোটিভেশন লাগে না। শুরু করো, মোটিভেশন পেছনে আসবে।"),
        G("A day well planned is half done.", "ভালোভাবে পরিকল্পিত দিন অর্ধেক কাজ শেষ।"),
        G("One task at a time. The phone can wait.", "একবারে একটি কাজ। ফোন অপেক্ষা করতে পারে।"),
        G("Discipline is choosing what you want most over what you want now.", "শৃঙ্খলা মানে এখন যা চাও তার বদলে যা সবচেয়ে বেশি চাও তা বেছে নেওয়া।"),
        G("Small steps every day add up to big changes.", "প্রতিদিনের ছোট পদক্ষেপ মিলে বড় পরিবর্তন হয়।"),
        G("Don't break the chain. Tick one thing today.", "ধারাবাহিকতা ভেঙো না। আজ অন্তত একটি কাজে টিক দাও।"),
        G("Progress, not perfection.", "নিখুঁত হওয়া নয়, এগিয়ে যাওয়াই আসল।"),
        G("If you missed yesterday, start again today. No guilt, just begin.", "গতকাল না হলে আজ আবার শুরু করো। অপরাধবোধ নয়, শুধু শুরু।"),
        G("Your future is built by what you do today, not tomorrow.", "তোমার ভবিষ্যৎ তৈরি হয় আজকের কাজ দিয়ে, আগামীকালের নয়।"),
        G("The hardest part is opening the book. Open it.", "সবচেয়ে কঠিন কাজ বই খোলা। খুলে ফেলো।"),
        G("Focus is a muscle. Train it 25 minutes at a time.", "মনোযোগ একটা পেশির মতো। ২৫ মিনিট করে অনুশীলন করো।"),
        G("Busy is not the same as productive.", "ব্যস্ত থাকা আর কাজের হওয়া এক জিনিস নয়।"),
        G("Finish what you started before starting something new.", "নতুন কিছু শুরুর আগে শুরু করা কাজটা শেষ করো।"),
        G("Clear desk, clear mind.", "পরিষ্কার টেবিল, পরিষ্কার মন।"),
        G("Hard work today, easier exams tomorrow.", "আজ পরিশ্রম, কাল পরীক্ষা সহজ।"),
        G("Revise today what you learned today.", "আজ যা শিখেছ, আজই একবার রিভিশন দাও।"),
        G("Ask the question in class. Confusion costs more than embarrassment.", "ক্লাসে প্রশ্ন করো। লজ্জার চেয়ে না বোঝার দাম বেশি।"),
        G("Write it down. A clear list calms a busy mind.", "লিখে ফেলো। পরিষ্কার তালিকা অস্থির মনকে শান্ত করে।"),
        G("Do the hardest task first, while your mind is fresh.", "মন সতেজ থাকতে থাকতে সবচেয়ে কঠিন কাজটা আগে করো।"),
        G("You are not behind. You are on your own timeline.", "তুমি পিছিয়ে নেই। তুমি নিজের সময়রেখায় চলছ।"),
        G("Comparison steals joy. Compare yourself only with yesterday's you.", "তুলনা আনন্দ কেড়ে নেয়। শুধু গতকালের নিজের সাথে তুলনা করো।"),
        G("Code a little every day; skill grows quietly.", "প্রতিদিন একটু কোড করো; দক্ষতা নীরবে বাড়ে।"),
        G("Every bug fixed is a lesson learned.", "প্রতিটি বাগ ঠিক করা মানে একটি নতুন শিক্ষা।"),
        G("Read one research paper section today. Just one.", "আজ একটি রিসার্চ পেপারের একটি অংশ পড়ো। শুধু একটি।"),
        G("Consistency turns ordinary students into great ones.", "ধারাবাহিকতা সাধারণ ছাত্রকে অসাধারণ বানায়।"),
        G("Waiting for the perfect time? It is now.", "সঠিক সময়ের অপেক্ষা? সেটা এখনই।"),
        G("Done is better than perfect.", "নিখুঁত হওয়ার চেয়ে শেষ করা ভালো।"),
        G("A short break is part of the work, not a failure.", "ছোট বিরতি কাজেরই অংশ, ব্যর্থতা নয়।"),
        G("Protect your mornings; they shape your whole day.", "সকালটা রক্ষা করো; সকালই পুরো দিন গড়ে।"),
        G("Plan tomorrow tonight, and wake up with a purpose.", "আজ রাতেই কালকের পরিকল্পনা করো, উদ্দেশ্য নিয়ে ঘুম থেকে ওঠো।"),
        G("Effort you put in quietly will speak loudly one day.", "নীরবে করা পরিশ্রম একদিন জোরে কথা বলবে।"),
        G("Learn something today that your future self will use.", "আজ এমন কিছু শেখো, যা ভবিষ্যতের তুমি কাজে লাগাবে।"),
        G("Mistakes mean you are trying. Keep trying.", "ভুল মানে তুমি চেষ্টা করছ। চেষ্টা চালিয়ে যাও।"),
        G("Ten pages a day is a book every month.", "দিনে দশ পৃষ্ঠা মানে মাসে একটি বই।"),
        G("Your attention is your most valuable asset. Spend it wisely.", "তোমার মনোযোগই সবচেয়ে মূল্যবান সম্পদ। বুঝে খরচ করো।"),
        G("Turn 'I have to' into 'I get to'.", "'আমাকে করতে হবে' কে বানাও 'আমি করার সুযোগ পেয়েছি'।"),
        G("Ambition without a schedule is just a wish.", "সময়সূচি ছাড়া লক্ষ্য শুধু একটি ইচ্ছা।"),
        G("Be the student your teachers remember for effort.", "এমন ছাত্র হও, যাকে শিক্ষকরা পরিশ্রমের জন্য মনে রাখেন।"),
        G("Today's effort is tomorrow's confidence.", "আজকের পরিশ্রম কালকের আত্মবিশ্বাস।"),
        G("When you feel stuck, make the next step smaller.", "আটকে গেলে পরের ধাপটা আরও ছোট করো।"),
        G("A tired mind learns nothing. Rest, then return.", "ক্লান্ত মন কিছু শেখে না। বিশ্রাম নাও, তারপর ফিরে আসো।"),
        G("You have survived every hard day so far. You will survive this one too.", "এ পর্যন্ত প্রতিটি কঠিন দিন পার করেছ। আজকেরটাও পার হবে।"),
        G("Slow progress is still progress.", "ধীর অগ্রগতিও অগ্রগতি।"),
        G("Win the morning, and the day follows.", "সকাল জিতলে দিনও জিতবে।"),
        G("Habits are built on easy days and tested on hard ones.", "অভ্যাস তৈরি হয় সহজ দিনে, পরীক্ষা হয় কঠিন দিনে।"),
        G("Don't count the days. Make the days count.", "দিন গুনো না, দিনগুলোকে মূল্যবান করো।"),
        G("Fall seven times, stand up eight.", "সাতবার পড়লে আটবার উঠে দাঁড়াও।"),
        G("Ideas are cheap. Finished projects are rare. Finish yours.", "আইডিয়া সস্তা, শেষ করা প্রজেক্ট বিরল। তোমারটা শেষ করো।"),
        G("Your degree opens the door; your skills keep you in the room.", "ডিগ্রি দরজা খোলে; দক্ষতা তোমাকে ঘরে টিকিয়ে রাখে।"),
        G("Learn in public: share what you build.", "যা শেখো, তা শেয়ার করো; যা বানাও, তা দেখাও।"),
        G("One page of notes after class saves three hours before exams.", "ক্লাসের পর এক পাতা নোট পরীক্ষার আগে তিন ঘণ্টা বাঁচায়।"),
        G("Choose progress over comfort, just for the next hour.", "শুধু পরের এক ঘণ্টার জন্য আরামের বদলে অগ্রগতি বেছে নাও।"),
        G("Starting late is better than never starting.", "দেরিতে শুরু করা কখনো শুরু না করার চেয়ে ভালো।"),
        G("A goal without a deadline drifts. Set the date.", "সময়সীমা ছাড়া লক্ষ্য ভেসে যায়। তারিখ ঠিক করো।"),
        G("Quiet hours, deep work, real results.", "নীরব সময়, গভীর কাজ, আসল ফলাফল।"),
        G("Teach what you learned today to someone. You'll learn it twice.", "আজ যা শিখলে কাউকে শেখাও। দুবার শেখা হবে।"),
        G("Be patient with yourself. Growth takes seasons, not days.", "নিজের প্রতি ধৈর্য রাখো। বড় হতে দিন নয়, ঋতু লাগে।"),
        G("Courage is doing it scared.", "ভয় নিয়েও কাজটা করাই সাহস।"),
        G("Keep promises to yourself the way you keep them to others.", "অন্যকে দেওয়া কথার মতো নিজেকে দেওয়া কথাও রাখো।"),

        // ============================================================ Sleep, morning, health
        G("Good sleep is not lazy. It is how your brain saves today's learning.", "ভালো ঘুম অলসতা নয়। এভাবেই মস্তিষ্ক আজকের শেখা জমা রাখে।"),
        G("Phone down, lights off. Tomorrow's you says thank you.", "ফোন রাখো, আলো নেভাও। কালকের তুমি ধন্যবাদ দেবে।"),
        G("Sleep early tonight and the morning won't feel like a fight.", "আজ তাড়াতাড়ি ঘুমাও, সকালটা যুদ্ধের মতো লাগবে না।"),
        G("Sunlight in the first hour wakes your body better than coffee.", "সকালের প্রথম ঘণ্টার রোদ কফির চেয়ে ভালোভাবে শরীর জাগায়।"),
        G("Drink a glass of water before you check your phone.", "ফোন দেখার আগে এক গ্লাস পানি পান করো।"),
        G("Wake up, make your bed. First task done.", "ঘুম থেকে উঠে বিছানা গোছাও। প্রথম কাজ শেষ।"),
        G("A 20-minute walk is cheaper than any medicine.", "২০ মিনিট হাঁটা যেকোনো ওষুধের চেয়ে সস্তা।"),
        G("Fajr on time makes the whole day feel lighter.", "সময়মতো ফজর পড়লে পুরো দিন হালকা লাগে।"),
