    val ALL: List<MotivationQuote> by lazy {
        ROWS.flatMapIndexed { i, r ->
            val (cat, srcEn, srcBn) = when (r) {
                is Q -> {
                    val (en, bn) = SURA[r.sura] ?: ("Surah ${r.sura}" to "সূরা ${r.sura}")
                    Triple(QuoteCategory.ISLAMIC, "Quran ${r.sura}:${r.ayah} ($en)", "সূরা $bn (${bnDigits("${r.sura}:${r.ayah}")})")
                }
                is H -> {
                    val num = r.num
                    val en = if (num.isBlank()) r.book.en else if (num.any(Char::isLetter)) num else "${r.book.en} $num"
                    val bn = if (num.isBlank()) r.book.bn else if (num.any(Char::isLetter)) "${r.book.bn} (${bnDigits(num.filter { it.isDigit() || it == ',' || it == ' ' }.trim())})" else "${r.book.bn} (${bnDigits(num)})"
                    Triple(QuoteCategory.ISLAMIC, en, bn)
                }
                is G -> Triple(QuoteCategory.PRODUCTIVITY, "Dinrekha", "দিনরেখা")
            }
            listOf(
                MotivationQuote(1000 + i * 2, r.en, srcEn, cat, QuoteLanguage.ENGLISH),
                MotivationQuote(1001 + i * 2, r.bn, srcBn, cat, QuoteLanguage.BANGLA),
            )
        }
    }
